test.config:
indexer
{
	mem_limit = 16M
}

searchd
{

}

source источник4770
{
	type = mysql

	sql_query_pre = SET NAMES utf8mb4
	sql_query = SELECT id, название, описание, цена FROM source_4770
	sql_attr_uint = цена
}

index обычная4770
{
	type = plain
	source = источник4770
	path = /plain4770
}

index таблица4770_rt
{
	type = rt
	path = /rt4770
	rt_field = название
	rt_field = описание
	rt_attr_uint = цена
	rt_attr_uint = ёмкость
	rt_attr_uint = 📦метка
}

index правила4770_cfg
{
	type = percolate
	path = /pq4770
	rt_field = название
	rt_field = описание
	rt_attr_uint = цена
}

index распределенная4770
{
	type = distributed
	local = таблица4770_rt
	local = обычная4770
}

index шаблон4770
{
	type = template
	charset_table = 0..9, A..Z->a..z, _, a..z, U+410..U+42F->U+430..U+44F, U+430..U+44F, U+401->U+451, U+451
}

# Preserve punctuation accepted by earlier releases when loading configured schemas.
index legacy-table4770
{
	type = rt
	path = /legacy_table4770
	rt_field = title
}

index legacy_field4770
{
	type = rt
	path = /legacy_field4770
	rt_field = title-text
	rt_attr_string = category-name
}

index legacy_pq4770
{
	type = percolate
	path = /legacy_pq4770
	rt_field = task.params
	rt_field = graph-workspace.description
}

queries.sphinxql:
SHOW TABLES;
INSERT INTO таблица4770_rt (id, название, описание, цена, ёмкость, 📦метка) VALUES
	(10, 'Клавиатура', 'Игровая клавиатура', 100, 75, 1);
SELECT id, название, цена FROM таблица4770_rt WHERE MATCH('@название клавиатура');
SELECT id, название, цена FROM обычная4770 WHERE MATCH('@название клавиатура');
SELECT id, название, цена FROM распределенная4770 WHERE MATCH('@название клавиатура');
INSERT INTO правила4770_cfg (id, query) VALUES (1, '@название клавиатура');
CALL PQ('правила4770_cfg', '{"название":"клавиатура","описание":"товар","цена":100}');
INSERT INTO legacy_pq4770 (id, query) VALUES (1, '@task.params hello'), (2, '@graph-workspace.description world');
CALL PQ('legacy_pq4770', '{"task.params":"hello","graph-workspace.description":"world"}');
CALL SNIPPETS('Игровая клавиатура', 'шаблон4770', 'клавиатура');

test.db_insert:
INSERT INTO source_4770 (id, `название`, `описание`, `цена`) VALUES
	(1, 'Клавиатура', 'Игровая клавиатура', 100),
	(2, 'Мышь', 'Игровая мышь', 60);
